let client = reqwest::Client::new();
let res = client.post("http://localhost:8000/v1/config/plugin/cluaiz-search/set")
    .json(&serde_json::json!({
        "type": "plugin",
        "id": "cluaiz-search",
        "key": "search_api_key",
        "value": "tvly-test-123"
    }))
    .send()
    .await?;
println!("{:#?}", res.json::<serde_json::Value>().await?);
